package com.dy.artisan3d.ui.screen.main.article.listimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport kotlinx.coroutines.asyncimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass ArticleListViewModel(    private val appLange: AppLanguage,    private val artisanArticleRepository: ArtisanArticleRepository,) : ViewModel() {    private val _uiState = MutableStateFlow(ArticleListUiState())    val uiState = _uiState.asStateFlow()    init {        fetchHomeData()    }    fun fetchHomeData(isRefresh: Boolean = false) {        // Agar allaqachon yuklangan bo'lsa va bu refresh bo'lmasa - so'rov yubormaymiz        if (!isRefresh && _uiState.value.isInitialized) return        viewModelScope.launch {            _uiState.update { it.copy(isLoading = true, isError = false) }            try {                val articlesDeferred = async { artisanArticleRepository.getArticles(1, appLange.current) }                val article = articlesDeferred.await()                _uiState.update {                    it.copy(                        articles = article,                        isLoading = false,                        isInitialized = true                    )                }            } catch (e: Exception) {                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        errorMessage = e.message ?: "Xatolik yuz berdi",                        isInitialized = true                    )                }            }        }    }}